// ticketId se extrae una sola vez, fuera del try: si el payload no trae
// ticketId no hay nada que reportar de vuelta, y así el catch nunca depende
// de volver a tocar $input (que ya funcionó una vez arriba).
const rawBody = ($input.first().json && $input.first().json.body) || $input.first().json || {};
const ticketId = rawBody.ticketId;

try {
  const title = String(rawBody.title || '').toLowerCase();
  const description = String(rawBody.description || '').toLowerCase();
  const text = `${title} ${description}`;

  // Reglas de clasificación por keywords, en orden de prioridad de match.
  const categoryRules = [
    { category: 'billing', keywords: ['factura', 'cobro', 'pago', 'suscripción', 'cancelación', 'reembolso'] },
    { category: 'technical', keywords: ['error', 'bug', 'no funciona', 'se cierra', 'crash', 'no carga', '500'] },
    { category: 'account', keywords: ['contraseña', 'email', 'cuenta', 'acceso', 'sesión', 'login'] },
  ];

  const priorityRules = [
    { priority: 'urgent', keywords: ['urgente', 'no puedo trabajar', 'crítico'] },
    { priority: 'high', keywords: ['error 500', 'cobro duplicado', 'no funciona', 'no puedo iniciar sesión'] },
    { priority: 'low', keywords: ['sugerencia', 'consulta', 'pregunta'] },
  ];

  const tags = [];

  let category = 'other';
  for (const rule of categoryRules) {
    const hit = rule.keywords.find((kw) => text.includes(kw));
    if (hit) {
      category = rule.category;
      tags.push(hit);
      break;
    }
  }

  let priority = 'medium';
  for (const rule of priorityRules) {
    const hit = rule.keywords.find((kw) => text.includes(kw));
    if (hit) {
      priority = rule.priority;
      tags.push(hit);
      break;
    }
  }

  return [{ json: { ticketId, status: 'done', priority, category, tags } }];
} catch (error) {
  return [{ json: { ticketId, status: 'failed' } }];
}
